function dnsFetch(root,provider,name,type){var query=dnsBuildQuery(name,type),url='api/dns-queryeb11.html?provider='+encodeURIComponent(provider),controller=window.AbortController?new AbortController():null;if(controller)root._yjDnsControllers.push(controller);return new Promise(function(resolve){var done=false,timer=setTimeout(function(){if(controller)controller.abort();finish({provider:provider,error:'查询超时'})},10000);function finish(value){if(done)return;done=true;clearTimeout(timer);resolve(value)}fetch(url,{method:'POST',credentials:'omit',cache:'no-store',referrerPolicy:'no-referrer',headers:{Accept:'application/dns-message','Content-Type':'application/dns-message'},body:query.bytes,signal:controller?controller.signal:undefined}).then(function(response){if(!response.ok)throw new Error('HTTP '+response.status);return response.arrayBuffer()}).then(function(buffer){var data=dnsParseResponse(buffer,query.id);finish({provider:provider,status:data.status,records:data.records,truncated:data.truncated})}).catch(function(){finish({provider:provider,error:'国内 DNS 服务暂时不可用'})})})}
