function dnsProviderHtml(item){var info=dnsProviders[item.provider],head='<header><b>'+escapeHtml(info.label)+'</b><span>'+escapeHtml(item.error?'查询失败':dnsStatus(item.status))+'</span></header>';if(item.error)return'<section class="yjcalc-dns-provider">'+head+'<p class="yjcalc-dns-empty">'+escapeHtml(item.error)+'；可稍后重试或改用另一来源。</p></section>';var rows=item.records.map(function(record){return'<div class="yjcalc-dns-row"><b>'+escapeHtml(record.type)+'</b><code>'+escapeHtml(record.data)+'</code><small>'+(record.ttl==null?'TTL —':'TTL '+record.ttl+' s')+'</small></div>'}).join('');if(!rows)rows='<p class="yjcalc-dns-empty">'+(item.status===3?'域名不存在（NXDOMAIN）。':'未查到该类型记录；也可能受解析缓存或地区影响。')+'</p>';return'<section class="yjcalc-dns-provider">'+head+rows+(item.truncated?'<p class="yjcalc-dns-empty">响应已截断，结果可能不完整。</p>':'')+'</section>'}
function dnsComparison(results){if(results.length<2)return'单源查询';if(results.some(function(item){return!!item.error}))return'部分来源查询失败，暂无法对照';if(results[0].status!==results[1].status)return'两侧 DNS 状态不同';var left=results[0].records.map(dnsRecordKey).sort().join('\n'),right=results[1].records.map(dnsRecordKey).sort().join('\n');if(left!==right)return'两侧记录不同（可能与缓存或地区有关）';return results[0].status===3?'两侧均返回 NXDOMAIN':'两侧记录一致（不比较 TTL）'}
function dnsRender(root,name,type,results){var panel=one(root,'[data-dns-results]'),summary=dnsComparison(results),time=new Date().toLocaleTimeString('zh-CN',{hour12:false});panel.innerHTML='<div class="yjcalc-dns-summary"><b>'+escapeHtml(name)+' · '+escapeHtml(type)+'</b><span>'+escapeHtml(summary)+' · '+escapeHtml(time)+'</span></div><div class="yjcalc-dns-grid'+(results.length===1?' single':'')+'">'+results.map(dnsProviderHtml).join('')+'</div><p class="yjcalc-note">公共递归 DNS 的结果可能因缓存、地理位置和策略不同而变化；生产变更请再核对权威 DNS。</p>';panel.hidden=false;root._yjDnsCopy=[name+' '+type+' · '+summary].concat(results.map(function(item){var label=dnsProviders[item.provider].label;if(item.error)return label+': '+item.error;return[label+' ('+dnsStatus(item.status)+')'].concat(item.records.length?item.records.map(function(record){return'  '+record.type+' '+record.data+'  TTL '+(record.ttl==null?'-':record.ttl)}):['  无记录']).join('\n')})).join('\n');dnsMessage(root,results.every(function(item){return!!item.error})?'查询失败，请检查网络或稍后重试。':'查询完成。结果仅保留在当前页面。',results.every(function(item){return!!item.error}))}
function dnsQuery(root){if(root.dataset.yjDnsLoading==='1')return;var name,type=one(root,'#yjcalc-dns-type').value,mode=one(root,'#yjcalc-dns-provider').value;try{name=dnsName(one(root,'#yjcalc-dns-name').value)}catch(error){dnsMessage(root,error.message,true);return}var providers=mode==='compare'?['aliyun','tencent']:[mode];if(providers.some(function(provider){return!dnsProviders[provider]}))return;root._yjDnsRequestId=(root._yjDnsRequestId||0)+1;var token=root._yjDnsRequestId,button=one(root,'[data-calc-action="dns-query"]');root._yjDnsControllers=[];root.dataset.yjDnsLoading='1';button.disabled=true;button.textContent='正在查询…';one(root,'[data-dns-results]').hidden=true;root._yjDnsCopy='';dnsMessage(root,'正在向所选国内公共 DNS 查询 '+name+' 的 '+type+' 记录…');Promise.all(providers.map(function(provider){return dnsFetch(root,provider,name,type)})).then(function(results){if(token!==root._yjDnsRequestId)return;dnsRender(root,name,type,results)}).catch(function(){if(token===root._yjDnsRequestId)dnsMessage(root,'查询失败，请稍后重试。',true)}).then(function(){if(token!==root._yjDnsRequestId)return;root.dataset.yjDnsLoading='0';button.disabled=false;button.textContent='查询记录';root._yjDnsControllers=[]})}
