function processMessage(root,message,isError){var box=one(root,'[data-process-message]');box.textContent=message;box.classList.toggle('error',!!isError)}
function processCsv(line){var cells=[],cell='',quoted=false;for(var i=0;i<line.length;i++){var ch=line[i];if(ch==='"'){if(quoted&&line[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){cells.push(cell.trim());cell=''}else cell+=ch}cells.push(cell.trim());return quoted?null:cells}
