function init(candidate){var root=candidate&&candidate.matches&&candidate.matches('.yj-ops-calc')?candidate:document.querySelector('.yj-ops-calc');if(!root||root.dataset.yjCalcReady)return;root.dataset.yjCalcReady='1';root.dataset.yjQrType='text';root.dataset.yjQrReady='0';root.dataset.yjPasswordMode='password';var date=one(root,'#yjcalc-date');if(date&&!date.value)date.value=localInputValue(new Date());root.addEventListener('click',function(event){var networkMode=event.target.closest('[data-network-mode]'),systemMode=event.target.closest('[data-system-mode]'),cronPreset=event.target.closest('[data-cron-value]'),qrTab=event.target.closest('[data-qr-tab]'),qrType=event.target.closest('[data-qr-type]'),passwordMode=event.target.closest('[data-password-mode]'),processSample=event.target.closest('[data-process-sample]'),button=event.target.closest('[data-calc-action]');if(networkMode&&root.contains(networkMode)){event.preventDefault();setNetworkMode(root,networkMode.getAttribute('data-network-mode'));return}if(systemMode&&root.contains(systemMode)){event.preventDefault();setSystemMode(root,systemMode.getAttribute('data-system-mode'));return}if(cronPreset&&root.contains(cronPreset)){event.preventDefault();one(root,'#yjcalc-cron').value=cronPreset.getAttribute('data-cron-value');calcCron(root);return}if(qrTab&&root.contains(qrTab)){event.preventDefault();setQrTab(root,qrTab.getAttribute('data-qr-tab'));return}if(qrType&&root.contains(qrType)){event.preventDefault();setQrType(root,qrType.getAttribute('data-qr-type'));return}if(passwordMode&&root.contains(passwordMode)){event.preventDefault();setPasswordMode(root,passwordMode.getAttribute('data-password-mode'));return}if(processSample&&root.contains(processSample)){event.preventDefault();one(root,'#yjcalc-process-input').value=processSamples[processSample.getAttribute('data-process-sample')]||'';processAnalyze(root);return}if(button&&root.contains(button)){event.preventDefault();run(root,button.getAttribute('data-calc-action'))}});root.addEventListener('input',function(event){if(event.target.id==='yjcalc-password-length')one(root,'#yjcalc-password-length-label').textContent=event.target.value;else if(event.target.id==='yjcalc-word-count')one(root,'#yjcalc-word-count-label').textContent=event.target.value;else if(event.target.id==='yjcalc-pin-length')one(root,'#yjcalc-pin-length-label').textContent=event.target.value});root.addEventListener('change',function(event){if(event.target.matches('[data-perm-row]'))updatePermissionFromGrid(root,event.target);else if(event.target.id==='yjcalc-qr-file')scanQrFile(root,event.target.files&&event.target.files[0]);else if(event.target.id==='yjcalc-qr-size'&&root.dataset.yjQrReady==='1')generateQr(root)});root.addEventListener('paste',function(event){var pane=one(root,'[data-qr-pane="scan"]');if(pane&&pane.hidden)return;var items=event.clipboardData&&event.clipboardData.items;if(!items)return;for(var i=0;i<items.length;i++){if(items[i].type.indexOf('image/')===0){var file=items[i].getAsFile();if(file){event.preventDefault();scanQrFile(root,file)}break}}});root.addEventListener('keydown',function(event){if(event.key==='Enter'&&event.target.matches('input:not([type="range"]):not([type="checkbox"]):not([type="file"])')){var pane=event.target.closest('[data-network-pane],[data-system-pane],.yjcalc-card'),button=pane&&pane.querySelector('[data-calc-action]');if(button)button.click()}});['ip','raid','transfer','ups'].forEach(function(name){run(root,name)});dateToTimestamp(root);setNetworkMode(root,'ipv4');setSystemMode(root,'hash');setQrType(root,'text');setQrTab(root,'generate');setPasswordMode(root,'password');renderPermissionGrid(root,'755');calcCron(root);calcChmod(root)}
function setDiagnosticMode(root,mode){root.querySelectorAll('[data-diagnostic-mode]').forEach(function(button){var active=button.getAttribute('data-diagnostic-mode')===mode;button.classList.toggle('active',active);button.setAttribute('aria-selected',active?'true':'false')});root.querySelectorAll('[data-diagnostic-pane]').forEach(function(pane){pane.hidden=pane.getAttribute('data-diagnostic-pane')!==mode})}
